const rows = $input.all().map(item => item.json);

const clamp = value => Math.max(0, Math.min(100, value));
const parseNumber = value => {
  if (value === null || value === undefined || value === '') return null;
  const parsed = Number(String(value).replace(/,/g, '').replace(/[^0-9.+-]/g, ''));
  return Number.isFinite(parsed) ? parsed : null;
};
const parseCompact = value => {
  const match = String(value || '').replace(/,/g, '').trim().match(/^([0-9]+(?:\.[0-9]+)?)([kKmM])?$/);
  if (!match) return parseNumber(value);
  const multiplier = match[2]?.toLowerCase() === 'k' ? 1000 : match[2]?.toLowerCase() === 'm' ? 1000000 : 1;
  return Math.round(Number(match[1]) * multiplier);
};
const pick = (text, pattern) => {
  const match = String(text || '').match(pattern);
  return match ? String(match[1]).trim() : null;
};
const countKeywords = (text, words) => words.filter(word => text.includes(word)).length;

const weights = {
  commuterFit: 0.20,
  commissionEconomics: 0.25,
  demand: 0.15,
  videoFit: 0.15,
  trust: 0.10,
  angleDepth: 0.10,
  seasonality: 0.05
};
const commuterWords = ['commuter', 'motorcycle', 'rain', 'waterproof', 'reflective', 'compact', 'portable', 'backpack', 'bottle', 'safety'];
const videoWords = ['waterproof', 'reflective', 'compact', 'adjustable', 'anti-slip', 'lightweight', 'foldable', 'insulated', 'breathable'];
const angleBuckets = [
  ['rain', 'waterproof', 'weather'],
  ['reflective', 'safety'],
  ['compact', 'foldable', 'portable'],
  ['adjustable', 'anti-slip', 'breathable'],
  ['storage', 'pouch', 'bag'],
  ['insulated', 'bottle', 'tumbler']
];

return rows.map(row => {
  const source = `${row.RawListingText || ''}\n${row.RawAffiliateMetrics || ''}`;
  const lower = source.toLowerCase();
  const productName = pick(row.RawListingText, /(?:^|\n)\s*Title\s*:\s*([^\n]+)/i);
  const category = pick(row.RawListingText, /(?:^|\n)\s*Category\s*:\s*([^\n]+)/i);
  const price = parseNumber(pick(source, /(?:^|\n)\s*Price\s*:\s*(?:PHP|P)?\s*([\d,.]+)/i));
  const commissionPercent = parseNumber(pick(row.RawAffiliateMetrics, /Commission\s*rate\s*:\s*([\d.]+)\s*%/i));
  const monthlySold = parseCompact(pick(source, /(?:^|\n)\s*Sold\s*:\s*([\d,.]+\s*[kKmM]?)/i));
  const rating = parseNumber(pick(source, /(?:^|\n)\s*Rating\s*:\s*([\d.]+)/i));
  const reviewCount = parseCompact(pick(source, /(?:^|\n)\s*Reviews\s*:\s*([\d,.]+\s*[kKmM]?)/i));

  const missing = [];
  if (!row.CandidateId) missing.push('CandidateId');
  if (!productName) missing.push('ProductName');
  if (!category) missing.push('Category');
  if (!(price > 0)) missing.push('Price');
  if (!(commissionPercent > 0)) missing.push('CommissionRate');
  if (!(monthlySold >= 0)) missing.push('MonthlySold');
  if (!(rating >= 1 && rating <= 5)) missing.push('Rating');
  if (!(reviewCount >= 0)) missing.push('ReviewCount');
  if (!row.FactsVerified) missing.push('FactsVerified');
  if (!row.RightsConfirmed) missing.push('RightsConfirmed');
  if (!row.ImageRightsEvidence) missing.push('ImageRightsEvidence');

  const estimatedCommission = price && commissionPercent ? price * (commissionPercent / 100) : null;
  const commuterFit = clamp(25 + countKeywords(lower, commuterWords) * 9);
  const videoFit = clamp(25 + countKeywords(lower, videoWords) * 8);
  const angleDepth = clamp(20 + angleBuckets.filter(bucket => bucket.some(word => lower.includes(word))).length * 13);
  const rainySeason = Number(row.ScoringMonth) >= 6 && Number(row.ScoringMonth) <= 11;
  const seasonality = /rain|waterproof|weather/.test(lower) ? (rainySeason ? 90 : 65) : 65;
  const commissionScore = estimatedCommission === null ? 0 : clamp(estimatedCommission);
  const demandScore = monthlySold === null ? 0 : clamp((Math.log10(1 + monthlySold) / 4) * 100);
  const ratingScore = rating === null ? 0 : clamp(((rating - 3.5) / 1.5) * 100);
  const reviewScore = reviewCount === null ? 0 : clamp((Math.log10(1 + reviewCount) / 4) * 100);
  const trustScore = ratingScore * 0.7 + reviewScore * 0.3;
  const eligible = missing.length === 0;
  const selectionScore = eligible ? Math.round((
    commuterFit * weights.commuterFit +
    commissionScore * weights.commissionEconomics +
    demandScore * weights.demand +
    videoFit * weights.videoFit +
    trustScore * weights.trust +
    angleDepth * weights.angleDepth +
    seasonality * weights.seasonality
  ) * 10) / 10 : null;

  return {
    json: {
      ...row,
      ProductName: productName,
      Category: category,
      PricePHP: price,
      CommissionRatePercent: commissionPercent,
      MonthlySold: monthlySold,
      Rating: rating,
      ReviewCount: reviewCount,
      EstimatedCommissionPHP: estimatedCommission === null ? null : Math.round(estimatedCommission * 100) / 100,
      ScoreComponents: {
        commissionEconomics: Math.round(commissionScore * 10) / 10,
        commuterFit,
        demand: Math.round(demandScore * 10) / 10,
        videoFit,
        trust: Math.round(trustScore * 10) / 10,
        angleDepth,
        seasonality
      },
      ScoringWeights: weights,
      Eligible: eligible,
      SelectionScore: selectionScore,
      SelectionReason: eligible ? 'Passed extraction, evidence, and media-rights gates' : `Needs: ${missing.join(', ')}`,
      ExtractionMode: 'USER_SUPPLIED_TEXT_ONLY',
      MarketplaceQueried: false
    }
  };
});

const evaluated = $input.all().map(item => item.json);
const ranked = evaluated
  .filter(candidate => candidate.Eligible)
  .sort((a, b) =>
    b.SelectionScore - a.SelectionScore ||
    b.EstimatedCommissionPHP - a.EstimatedCommissionPHP ||
    b.MonthlySold - a.MonthlySold ||
    a.CandidateId.localeCompare(b.CandidateId)
  )
  .map((candidate, index) => ({ ...candidate, Rank: index + 1 }));

if (!ranked.length) throw new Error('No candidate passed the extraction, evidence, and rights gates');

return [{
  json: {
    RunStatus: 'TOP_CANDIDATE_READY',
    Niche: 'Practical Commuter Finds',
    CandidateCount: evaluated.length,
    EligibleCount: ranked.length,
    RankingMethod: 'DETERMINISTIC_WEIGHTED_SCORE',
    SelectedCandidate: ranked[0],
    RankedCandidates: ranked.map(candidate => ({
      CandidateId: candidate.CandidateId,
      ProductName: candidate.ProductName,
      Rank: candidate.Rank,
      SelectionScore: candidate.SelectionScore,
      EstimatedCommissionPHP: candidate.EstimatedCommissionPHP,
      ScoreComponents: candidate.ScoreComponents
    })),
    PaidGenerationTriggered: false,
    PublishingTriggered: false
  }
}];

const input = $input.first().json;
const product = input.SelectedCandidate;
const facts = product.VerifiedFacts;
const sentence = value => `${String(value).trim().replace(/[.!?]+$/, '')}.`;
const hook = `Rainy commute? Here is one practical ${product.Category.toLowerCase()} option to review.`;
const proof = `Fixture detail: ${sentence(facts[0])}`;
const cta = 'Review the product details and tagged affiliate item before publishing.';
const disclosure = product.Disclosure;
const spokenCopy = [hook, proof, cta].join(' ');
const prohibitedClaims = ['best', 'guaranteed', 'lowest price', 'limited stock', 'risk-free'];
const blockedClaim = prohibitedClaims.find(claim => spokenCopy.toLowerCase().includes(claim));
if (blockedClaim) throw new Error(`Script used prohibited claim: ${blockedClaim}`);

return [{
  json: {
    ...input,
    Creative: {
      Script: {
        Structure: 'HOOK_PROOF_CTA',
        Hook: hook,
        Proof: proof,
        SupportingFacts: facts.slice(1).map(sentence),
        CTA: cta,
        SpokenCopy: spokenCopy,
        Disclosure: disclosure,
        OnScreenTextPlan: 'Add verified text and disclosure deterministically after video generation.'
      },
      ClaimPolicy: {
        AllowedFacts: facts,
        ProhibitedClaims: prohibitedClaims,
        PricePolicy: 'Recheck price and availability at manual publishing time.'
      },
      Format: {
        AspectRatio: '9:16',
        Width: 720,
        Height: 1280,
        FramesPerSecond: 24,
        TargetSeconds: 8
      }
    }
  }
}];

const input = $input.first().json;
const product = input.SelectedCandidate;
const creative = input.Creative;
if (!product.ReferenceAsset || !product.RightsConfirmed) {
  throw new Error('Storyboard requires a fictional or rights-cleared reference asset');
}

const shot = {
  ShotId: 'DEMO-SHOT-01',
  DurationSeconds: 8,
  Task: 'IMAGE_TO_VIDEO',
  ReferenceAsset: product.ReferenceAsset,
  ImageRole: 'FIRST_FRAME',
  Framing: 'Medium vertical smartphone product shot with the item inside the safe area.',
  CameraMotion: 'One slow restrained push-in with subtle natural handheld movement.',
  SubjectAction: 'One small natural movement demonstrates the product while its construction and proportions remain unchanged.',
  EnvironmentMotion: 'Light rain and faint background motion remain natural and secondary to the product.',
  Lighting: 'Soft overcast daylight with realistic reflections and restrained contrast.',
  Audio: 'Environmental ambience only; no dialogue and no music.',
  ContinuityAnchors: [
    'Preserve exact product shape, color, proportions, construction, and visible features.',
    'Preserve the supplied composition as the opening frame.',
    'Keep all people, objects, and relative positions structurally unchanged.'
  ],
  ForbiddenChanges: [
    'Invented text, price, discounts, badges, labels, or promotional graphics.',
    'Product, face, hand, body, vehicle, or accessory morphing.',
    'Extra people, objects, scene cuts, or unrealistic weather effects.'
  ],
  ScriptReference: {
    Hook: creative.Script.Hook,
    ProofFact: product.VerifiedFacts[0],
    CTA: creative.Script.CTA
  }
};
const validation = {
  ExactlyOneShot: true,
  DurationSupported: shot.DurationSeconds >= 3 && shot.DurationSeconds <= 10,
  Portrait: creative.Format.AspectRatio === '9:16',
  HasReferenceAsset: Boolean(shot.ReferenceAsset),
  HasContinuityAnchors: shot.ContinuityAnchors.length >= 3,
  HasForbiddenChanges: shot.ForbiddenChanges.length >= 3,
  UsesVerifiedFact: product.VerifiedFacts.includes(shot.ScriptReference.ProofFact),
  NoGeneratedDialogue: shot.Audio.includes('no dialogue')
};
if (!Object.values(validation).every(Boolean)) {
  throw new Error(`Storyboard validation failed: ${JSON.stringify(validation)}`);
}

return [{
  json: {
    ...input,
    Creative: {
      ...creative,
      Storyboard: [shot],
      StoryboardValidation: validation
    }
  }
}];

const input = $input.first().json;
const shot = input.Creative.Storyboard[0];
const validation = input.Creative.StoryboardValidation;
if (!Object.values(validation).every(Boolean)) throw new Error('Refusing to compile an invalid storyboard');

const prompt = [
  '<FIRST_FRAME>',
  'Continuous unbroken portrait smartphone shot with no scene cuts.',
  shot.Framing,
  `Camera movement: ${shot.CameraMotion}`,
  `Subject action: ${shot.SubjectAction}`,
  `Environmental motion: ${shot.EnvironmentMotion}`,
  `Lighting: ${shot.Lighting}`,
  `Sound: ${shot.Audio}`,
  `Continuity requirements: ${shot.ContinuityAnchors.join('; ')}`,
  `Do not add: ${shot.ForbiddenChanges.join('; ')}`,
  'Use the supplied product reference as the starting frame and keep everything else unchanged.'
].join(' ');

return [{
  json: {
    ...input,
    GenerationAdapter: {
      Status: 'DISABLED',
      RequestStatus: 'COMPILED_NOT_SUBMITTED',
      Provider: 'NOT_CONFIGURED',
      Task: shot.Task,
      Prompt: prompt,
      RequestTemplate: {
        Input: ['RIGHTS_CLEARED_REFERENCE_ASSET', 'VALIDATED_STORYBOARD_PROMPT'],
        Output: 'VERTICAL_VIDEO_URI',
        DurationSeconds: shot.DurationSeconds,
        AspectRatio: input.Creative.Format.AspectRatio
      },
      RequiredProductionGates: [
        'explicit per-run budget approval',
        'approved provider model and terms',
        'rights evidence',
        'attributable human authorization'
      ],
      PaidGenerationRequests: 0,
      PaidGenerationTriggered: false
    }
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,
    Approval: {
      Status: 'REQUIRED_MANUAL_REVIEW',
      Approved: false,
      CanPublish: false,
      RequiredReview: [
        'actual rendered video and product fidelity',
        'current product facts, seller, price, and availability',
        'affiliate and synthetic-media disclosures',
        'reference, music, and overlay rights',
        'platform format, product tags, and caption',
        'provider request receipt and final cost'
      ],
      NextProductionControl: 'Attributable approve or reject response tied to the exact media hash'
    }
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,
    Handoff: {
      Platform: input.TargetPlatform || 'social_commerce_channel',
      Mode: 'MANUAL_REVIEW_PACKAGE',
      DirectPostingEnabled: false,
      VideoAttached: false,
      ProductTagAttached: false,
      CaptionPreview: `${input.Creative.Script.SpokenCopy} ${input.Creative.Script.Disclosure}`,
      Checklist: input.Approval.RequiredReview,
      Status: 'BLOCKED_PENDING_GENERATION_AND_HUMAN_APPROVAL'
    }
  }
}];

const input = $input.first().json;

return [{
  json: {
    status: 'NOT_PUBLISHED',
    selectedCandidateId: input.SelectedCandidate.CandidateId,
    selectedProductName: input.SelectedCandidate.ProductName,
    candidateCount: input.CandidateCount,
    eligibleCount: input.EligibleCount,
    paidGenerationRequests: input.GenerationAdapter.PaidGenerationRequests,
    paidGenerationTriggered: input.GenerationAdapter.PaidGenerationTriggered,
    publishingTriggered: false,
    humanApprovalRequired: input.Approval.Status === 'REQUIRED_MANUAL_REVIEW',
    platform: input.Handoff.Platform
  }
}];
